effect.shader:
const int TAPS = 8;
void main(){
  vec2 uv = acScreenNorm;
  float ar = acScreenSize.x / max(acScreenSize.y, 1.0);
  float d = length((uv - vec2(0.5)) * vec2(ar, 1.0));
  float amt = smoothstep(focusRadius, focusRadius + falloff, d) * strength * mixAmt;
  float r = amt * 0.035;
  vec4 sum = texture2DCv(inputImg.texture, uv);
  for (int i = 0; i < TAPS; i++){
    float ang = float(i) * 6.2831853 / float(TAPS);
    vec2 o = vec2(cos(ang), sin(ang)) * r;
    sum += texture2DCv(inputImg.texture, uv + o);
  }
  gl_FragColor = sum / float(TAPS + 1);
}
